import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';

import Home from './components/Web/Pages/Home/Home';
import Network from './components/Web/Pages/Home/Network';
import Commission from './components/Web/Pages/Home/Commission';
import AddCommission from './components/Web/Pages/Home/AddCommission';
import AddNetworkSoftware from './components/Web/Pages/Home/AddNetworkSoftware';
import Users from './components/Web/Pages/Home/Users';
import About from './components/Web/Pages/About/About';
import NetworkSoftware from './components/Web/Pages/Home/NetworkSoftware';

import './App.css';

const App = () => {
  return (
    <Router>
      <div>
        {/* <NavBar /> */}
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/about" element={<About />} />
          <Route path="/network" element={<Network />} />
          <Route path="/commission" element={<Commission />} />
          <Route path="/addcommission" element={<AddCommission />} />
          <Route path="/users" element={<Users />} />
          <Route path="/networksoftware" element={<NetworkSoftware />} />
          <Route path="/networksoftwarecreate" element={<AddNetworkSoftware />} />
          <Route path="/networksoftwarecreate" element={<AddNetworkSoftware />} />
        </Routes>
        {/* <Footer /> */}
      </div>
    </Router>
  );
};

export default App;
